import{_ as e,c as n,o as i,a0 as r}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Einführung in das mentale Spiel – Präsentationsfolien für den Moderator","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/de/facilitator-slides.md","filePath":"public/downloads/de/facilitator-slides.md"}');const a=e({name:"public/downloads/de/facilitator-slides.md"},[["render",function(e,t,a,s,l,o){return i(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="einfuhrung-in-das-mentale-spiel-–-prasentationsfolien-fur-den-moderator" tabindex="-1">Einführung in das mentale Spiel – Präsentationsfolien für den Moderator <a class="header-anchor" href="#einfuhrung-in-das-mentale-spiel-–-prasentationsfolien-fur-den-moderator" aria-label="Permalink to &quot;Einführung in das mentale Spiel – Präsentationsfolien für den Moderator&quot;">​</a></h1><p><strong>Pétanque-Akademie</strong><em>Leitfaden für Kursleiter</em></p><hr><h2 id="folie-1-willkommen" tabindex="-1">Folie 1: Willkommen <a class="header-anchor" href="#folie-1-willkommen" aria-label="Permalink to &quot;Folie 1: Willkommen&quot;">​</a></h2><h1 id="🎯-einfuhrung-in-das-mentale-spiel" tabindex="-1">🎯 Einführung in das mentale Spiel <a class="header-anchor" href="#🎯-einfuhrung-in-das-mentale-spiel" aria-label="Permalink to &quot;🎯 Einführung in das mentale Spiel&quot;">​</a></h1><p><strong>Für Elite-Pétanque-Spieler</strong></p><h3 id="heute-erfahren-sie" tabindex="-1">Heute erfahren Sie: <a class="header-anchor" href="#heute-erfahren-sie" aria-label="Permalink to &quot;Heute erfahren Sie:&quot;">​</a></h3><ul><li>🧠 Wie man die richtigen Bedingungen für die „Zone“ schafft</li><li>💪 Wie du deinen inneren Kritiker zum Schweigen bringst</li><li>🎪 Praktische Werkzeuge, die auch unter Druck funktionieren</li></ul><p><strong>Macht euch bereit für eine interaktive Session!</strong></p><hr><h2 id="folie-2-kurze-umfrage-–-wer-ist-dabei-🙋" tabindex="-1">Folie 2: Kurze Umfrage – Wer ist dabei? 🙋 <a class="header-anchor" href="#folie-2-kurze-umfrage-–-wer-ist-dabei-🙋" aria-label="Permalink to &quot;Folie 2: Kurze Umfrage – Wer ist dabei? 🙋&quot;">​</a></h2><h3 id="wer-hat-das-schon-erlebt" tabindex="-1">Wer hat das schon erlebt? <a class="header-anchor" href="#wer-hat-das-schon-erlebt" aria-label="Permalink to &quot;Wer hat das schon erlebt?&quot;">​</a></h3><p><strong>Hebt die Hand, wenn ihr jemals:</strong></p><ol><li><p>Im Training einen perfekten Wurf getroffen... und dann im Wettkampf daneben geschossen? 🎯❌</p></li><li><p>Hatten Sie das Gefühl, Ihre Gedanken rasten, obwohl Sie ruhig bleiben mussten? 🧠💨</p></li><li><p>Hast du dich nach einem Fehler selbst kritisiert? 😤</p></li><li><p>Hattet ihr schon mal ein Spiel, bei dem einfach alles „passt“? ✨</p></li></ol><p>Du bist nicht allein! Lass uns das gemeinsam lösen.</p><hr><h2 id="folie-3-das-paradoxon-der-elite-spieler" tabindex="-1">Folie 3: Das Paradoxon der Elite-Spieler <a class="header-anchor" href="#folie-3-das-paradoxon-der-elite-spieler" aria-label="Permalink to &quot;Folie 3: Das Paradoxon der Elite-Spieler&quot;">​</a></h2><h3 id="sie-verfugen-bereits-uber-die-fahigkeiten-warum-also" tabindex="-1">Sie verfügen bereits über die Fähigkeiten... Warum also? <a class="header-anchor" href="#sie-verfugen-bereits-uber-die-fahigkeiten-warum-also" aria-label="Permalink to &quot;Sie verfügen bereits über die Fähigkeiten... Warum also?&quot;">​</a></h3><p><strong>✅ Du HAST:</strong></p><ul><li>Hervorragende Technik (tausende von Stunden)</li><li>Jahrelange Erfahrung</li><li>Körperliche Fähigkeiten</li></ul><p><strong>❌ Aber du hast Schwierigkeiten mit:</strong></p><ul><li>Zugriff auf diese Technik unter Druck</li><li>Beständigkeit im Wettbewerb</li><li>Nach Fehlern wieder auf die Beine kommen</li></ul><h3 id="das-fehlende-puzzleteil-🧩" tabindex="-1">Das fehlende Puzzleteil? 🧩 <a class="header-anchor" href="#das-fehlende-puzzleteil-🧩" aria-label="Permalink to &quot;Das fehlende Puzzleteil? 🧩&quot;">​</a></h3><p><strong>Deine mentale Stärke.</strong></p><p><em>„Der Unterschied zwischen gut und großartig liegt in dem, was zwischen Ihren Ohren passiert.“</em></p><hr><h2 id="folie-4-die-zone-–-du-kennst-dieses-gefuhl-⚡" tabindex="-1">Folie 4: Die Zone – Du kennst dieses Gefühl! ⚡ <a class="header-anchor" href="#folie-4-die-zone-–-du-kennst-dieses-gefuhl-⚡" aria-label="Permalink to &quot;Folie 4: Die Zone – Du kennst dieses Gefühl! ⚡&quot;">​</a></h2><h3 id="erinnert-ihr-euch-an-dieses-perfekte-spiel" tabindex="-1">Erinnert ihr euch an dieses perfekte Spiel? <a class="header-anchor" href="#erinnert-ihr-euch-an-dieses-perfekte-spiel" aria-label="Permalink to &quot;Erinnert ihr euch an dieses perfekte Spiel?&quot;">​</a></h3><p><strong>Alles fühlte sich so an:</strong></p><ul><li>⏱️ Die Zeit verlangsamte sich</li><li>🎯 Mühelos und automatisch</li><li>🧘 Vollkommen konzentriert</li><li>🎪 Als ob du es verpassen könntest</li></ul><h3 id="das-ist-quot-die-zone-quot-flow-zustand" tabindex="-1">Das ist &quot;Die Zone&quot; (Flow-Zustand). <a class="header-anchor" href="#das-ist-quot-die-zone-quot-flow-zustand" aria-label="Permalink to &quot;Das ist &amp;quot;Die Zone&amp;quot; (Flow-Zustand).&quot;">​</a></h3><p><strong>Die Frage:</strong> Wie können wir regelmäßig darauf zugreifen, nicht nur zufällig?</p><p><strong>Die Antwort:</strong><em>Die zwei Denkweisen verstehen...</em></p><hr><h2 id="folie-5-dein-gehirn-hat-zwei-modi-🧠" tabindex="-1">Folie 5: Dein Gehirn hat zwei Modi 🧠 <a class="header-anchor" href="#folie-5-dein-gehirn-hat-zwei-modi-🧠" aria-label="Permalink to &quot;Folie 5: Dein Gehirn hat zwei Modi 🧠&quot;">​</a></h2><h3 id="🤔-planungsmodus-analytisches-denken" tabindex="-1">🤔 PLANUNGSMODUS (Analytisches Denken) <a class="header-anchor" href="#🤔-planungsmodus-analytisches-denken" aria-label="Permalink to &quot;🤔 PLANUNGSMODUS (Analytisches Denken)&quot;">​</a></h3><p><strong>Anwendungszeitpunkt:</strong> VOR der Aufnahme</p><ul><li>📊 Analyse des Geländes</li><li>🎯 Die Wahl deiner Strategie</li><li>⚖️ Abwägung der Risiken</li><li>🤝 Die richtige Aufnahme auswählen</li></ul><h3 id="🎯-ausfuhrungsmodus-flow-brain" tabindex="-1">🎯 Ausführungsmodus (Flow Brain) <a class="header-anchor" href="#🎯-ausfuhrungsmodus-flow-brain" aria-label="Permalink to &quot;🎯 Ausführungsmodus (Flow Brain)&quot;">​</a></h3><p><strong>Wann anwenden:</strong> WÄHREND der Aufnahme</p><ul><li>💪 Vertraue deinem Körper</li><li>🚫 Nicht über die Technik nachdenken</li><li>⏰ Nur im gegenwärtigen Moment</li><li>🤖 Automatische Leistung</li></ul><h3 id="⚠️-das-problem" tabindex="-1">⚠️ DAS PROBLEM: <a class="header-anchor" href="#⚠️-das-problem" aria-label="Permalink to &quot;⚠️ DAS PROBLEM:&quot;">​</a></h3><p><strong>Die meisten Spieler bleiben während der Ausführung im Planungsmodus!</strong><em>Ihr analytisches Denken beeinträchtigt Ihre automatischen Abläufe.</em></p><hr><h2 id="folie-6-der-schalter-–-ihre-geheimwaffe-🔄" tabindex="-1">Folie 6: Der Schalter – Ihre Geheimwaffe 🔄 <a class="header-anchor" href="#folie-6-der-schalter-–-ihre-geheimwaffe-🔄" aria-label="Permalink to &quot;Folie 6: Der Schalter – Ihre Geheimwaffe 🔄&quot;">​</a></h2><h3 id="meistere-diese-eine-fahigkeit" tabindex="-1">Meistere diese eine Fähigkeit: <a class="header-anchor" href="#meistere-diese-eine-fahigkeit" aria-label="Permalink to &quot;Meistere diese eine Fähigkeit:&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BEFORE the shot:          DURING the shot:</span></span>\n<span class="line"><span>🤔 Planning Mode    →     🎯 Execution Mode</span></span></code></pre></div><h3 id="der-prozess" tabindex="-1">Der Prozess: <a class="header-anchor" href="#der-prozess" aria-label="Permalink to &quot;Der Prozess:&quot;">​</a></h3><p><strong>1️⃣ VORHER (10-15 Sekunden):</strong></p><ul><li>🤔 Analysiere alles</li><li>📊 Plane deine Strategie</li><li>✅ Triff deine Entscheidung</li></ul><p><strong>2️⃣ DER SCHALTER (3 Atemzüge):</strong></p><ul><li>🌬️ Tief durchatmen</li><li>🧘 Mach deinen Kopf frei</li><li>🔄 Lass die Analyse los.</li></ul><p><strong>3️⃣ WÄHREND (2-3 Sekunden):</strong></p><ul><li>🎯 Vollkommenes Vertrauen</li><li>🤖 Lass es geschehen</li><li>⚡ Automatisch ausführen</li></ul><p><strong>Üben Sie diesen Schalter = Zugriff auf den Datenfluss bei Bedarf!</strong></p><hr><h2 id="folie-7-aktivitat-–-jetzt-ausprobieren-🎯" tabindex="-1">Folie 7: AKTIVITÄT – Jetzt ausprobieren! 🎯 <a class="header-anchor" href="#folie-7-aktivitat-–-jetzt-ausprobieren-🎯" aria-label="Permalink to &quot;Folie 7: AKTIVITÄT – Jetzt ausprobieren! 🎯&quot;">​</a></h2><h3 id="lasst-uns-den-wechsel-uben-2-minuten" tabindex="-1">Lasst uns den Wechsel üben (2 Minuten) <a class="header-anchor" href="#lasst-uns-den-wechsel-uben-2-minuten" aria-label="Permalink to &quot;Lasst uns den Wechsel üben (2 Minuten)&quot;">​</a></h3><p><strong>Alle aufstehen!</strong></p><ol><li><p><strong>Planungsmodus (10 Sek.):</strong> Stellen Sie sich vor, Sie analysieren einen Schuss. Denken Sie an das Gelände, die Strategie und die Risiken.</p></li><li><p><strong>Der Schalter (3 Atemzüge):</strong> Atme dreimal tief durch. Befreie deinen Geist mit jedem Ausatmen.</p></li><li><p><strong>Ausführungsmodus (3 Sek.):</strong> Stell dir vor, du wirfst. Kein Nachdenken. Einfach Vertrauen und Flow.</p></li></ol><p><strong>Wie hat sich das angefühlt? Anders?</strong></p><p><em>Setz dich hin und lass uns reden...</em></p><hr><h2 id="folie-8-triff-deinen-inneren-kritiker-😈" tabindex="-1">Folie 8: Triff deinen inneren Kritiker 😈 <a class="header-anchor" href="#folie-8-triff-deinen-inneren-kritiker-😈" aria-label="Permalink to &quot;Folie 8: Triff deinen inneren Kritiker 😈&quot;">​</a></h2><h3 id="kommt-ihnen-diese-stimme-bekannt-vor" tabindex="-1">Kommt Ihnen diese Stimme bekannt vor? <a class="header-anchor" href="#kommt-ihnen-diese-stimme-bekannt-vor" aria-label="Permalink to &quot;Kommt Ihnen diese Stimme bekannt vor?&quot;">​</a></h3><p><strong>Nach einem missglückten Schuss:</strong></p><ul><li>💢 &quot;Das war SCHRECKLICH!&quot;</li><li>😤 &quot;Du machst unter Druck IMMER Fehler!&quot;</li><li>😰 „Alle sehen dir beim Scheitern zu!“</li><li>😞 &quot;Du bist einfach nicht gut genug!&quot;</li></ul><h3 id="kurze-umfrage-🙋" tabindex="-1">Kurze Umfrage: 🙋 <a class="header-anchor" href="#kurze-umfrage-🙋" aria-label="Permalink to &quot;Kurze Umfrage: 🙋&quot;">​</a></h3><p><strong>Wer hört diese Stimme regelmäßig?</strong></p><h3 id="die-wahrheit" tabindex="-1">Die Wahrheit: <a class="header-anchor" href="#die-wahrheit" aria-label="Permalink to &quot;Die Wahrheit:&quot;">​</a></h3><p><strong>Dein innerer Kritiker versucht zu helfen...</strong><em>Aber es beeinträchtigt Ihre Leistung tatsächlich.</em></p><hr><h2 id="folie-9-entlasse-deinen-kritiker-engagiere-deinen-coach-🔄" tabindex="-1">Folie 9: Entlasse deinen Kritiker, engagiere deinen Coach! 🔄 <a class="header-anchor" href="#folie-9-entlasse-deinen-kritiker-engagiere-deinen-coach-🔄" aria-label="Permalink to &quot;Folie 9: Entlasse deinen Kritiker, engagiere deinen Coach! 🔄&quot;">​</a></h2><h3 id="die-verwandlung" tabindex="-1">Die Verwandlung: <a class="header-anchor" href="#die-verwandlung" aria-label="Permalink to &quot;Die Verwandlung:&quot;">​</a></h3><table tabindex="0"><thead><tr><th>😈 Innerer Kritiker</th><th>➡️</th><th>😊 Innerer Coach</th></tr></thead><tbody><tr><td>&quot;Du vermasselst es IMMER!&quot;</td><td>→</td><td>&quot;Diesen Wurf habe ich schon 1000 Mal gemacht.&quot;</td></tr><tr><td>&quot;Das war SCHRECKLICH!&quot;</td><td>→</td><td>&quot;Was kann ich daraus lernen?&quot;</td></tr><tr><td>&quot;Alle verurteilen dich!&quot;</td><td>→</td><td>&quot;Konzentriere dich auf MEIN Spiel, nicht auf ihre Meinungen&quot;</td></tr><tr><td>&quot;Du bist nicht gut genug!&quot;</td><td>→</td><td>&quot;Ich verbessere mich jeden Tag&quot;</td></tr></tbody></table><h3 id="die-auswirkungen" tabindex="-1">Die Auswirkungen: <a class="header-anchor" href="#die-auswirkungen" aria-label="Permalink to &quot;Die Auswirkungen:&quot;">​</a></h3><p><strong>Kritiker = Angst, Anspannung, schlechte Leistung</strong><strong>Coach = Selbstvertrauen, Entspannung, Höchstleistung</strong></p><hr><h2 id="folie-10-aktivitat-–-uberdenke-deine-innere-stimme-💬" tabindex="-1">Folie 10: AKTIVITÄT – Überdenke deine innere Stimme! 💬 <a class="header-anchor" href="#folie-10-aktivitat-–-uberdenke-deine-innere-stimme-💬" aria-label="Permalink to &quot;Folie 10: AKTIVITÄT – Überdenke deine innere Stimme! 💬&quot;">​</a></h2><h3 id="partnerubung-3-minuten" tabindex="-1">Partnerübung (3 Minuten) <a class="header-anchor" href="#partnerubung-3-minuten" aria-label="Permalink to &quot;Partnerübung (3 Minuten)&quot;">​</a></h3><p><strong>Wende dich an die Person neben dir:</strong></p><p><strong>Person A (1,5 Min.):</strong></p><ol><li>Teile eine Aussage deines inneren Kritikers mit.</li><li>Ein Partner hilft Ihnen dabei, es als inneren Coach neu zu interpretieren.</li><li>Schreibe den neuen Satz auf</li></ol><p><strong>Person B (1,5 Min.):</strong></p><ol><li>Gleiches Verfahren</li><li>Teile deine Gedanken mit deinem inneren Kritiker</li><li>Holen Sie sich Hilfe, um es anders zu formulieren.</li></ol><p><strong>Bereit? Los!</strong></p><p><em>Wir werden der Gruppe anschließend einige Beispiele vorstellen...</em></p><hr><h2 id="folie-11-werkzeug-nr-1-–-der-3-atemzug-reset-🌬️" tabindex="-1">Folie 11: Werkzeug Nr. 1 – Der 3-Atemzug-Reset 🌬️ <a class="header-anchor" href="#folie-11-werkzeug-nr-1-–-der-3-atemzug-reset-🌬️" aria-label="Permalink to &quot;Folie 11: Werkzeug Nr. 1 – Der 3-Atemzug-Reset 🌬️&quot;">​</a></h2><h3 id="ihr-notentlastungsventil" tabindex="-1">Ihr Notentlastungsventil <a class="header-anchor" href="#ihr-notentlastungsventil" aria-label="Permalink to &quot;Ihr Notentlastungsventil&quot;">​</a></h3><p><strong>Verwenden Sie dies, wenn:</strong></p><ul><li>😤 Du hast gerade einen Fehler gemacht.</li><li>😰 Du spürst, wie der Druck steigt.</li><li>🤯 Deine Gedanken rasen</li></ul><h3 id="der-prozess-1" tabindex="-1">Der Prozess: <a class="header-anchor" href="#der-prozess-1" aria-label="Permalink to &quot;Der Prozess:&quot;">​</a></h3><p><strong>🌬️ ATEMZUG 1 (4 Sek. einatmen):</strong> Achten Sie darauf, wo Sie Anspannung spüren (Schultern? Kiefer? Magen?).</p><p><strong>🌬️ ATEMZUG 2 (6 Sek. ausatmen):</strong> Lass die Anspannung los. Lass sie mit deinem Atem entweichen.</p><p><strong>🌬️ ATEMZUG 3 (Einatmen 4, Ausatmen 6):</strong> Konzentriere dich auf JETZT. Diese Aufnahme. Diesen Moment. Nichts anderes.</p><p><strong>⏱️ Dauert 20 Sekunden. Verändert alles.</strong></p><hr><h2 id="folie-12-demo-–-jeder-sollte-es-ausprobieren-🌬️" tabindex="-1">Folie 12: DEMO – Jeder sollte es ausprobieren! 🌬️ <a class="header-anchor" href="#folie-12-demo-–-jeder-sollte-es-ausprobieren-🌬️" aria-label="Permalink to &quot;Folie 12: DEMO – Jeder sollte es ausprobieren! 🌬️&quot;">​</a></h2><h3 id="_3-atemzug-reset-ubung-1-minute" tabindex="-1">3-Atemzug-Reset-Übung (1 Minute) <a class="header-anchor" href="#_3-atemzug-reset-ubung-1-minute" aria-label="Permalink to &quot;3-Atemzug-Reset-Übung (1 Minute)&quot;">​</a></h3><p><strong>Alle schließen die Augen...</strong></p><p><strong>Atemzug 1:</strong><em>Vier Minuten lang einatmen... Wo spüren Sie Anspannung?</em></p><p><strong>Atemzug 2:</strong><em>Sechs Mal ausatmen... Loslassen...</em></p><p><strong>Atemzug 3:</strong><em>Vier Minuten rein, sechs Minuten raus... Nur der gegenwärtige Moment...</em></p><p>Öffne deine Augen. Wie fühlst du dich?</p><p><em>Das ist Ihr Reset-Knopf. Benutzen Sie ihn!</em></p><hr><h2 id="folie-13-werkzeug-nr-2-–-deine-vorbereitungsroutine-🎯" tabindex="-1">Folie 13: Werkzeug Nr. 2 – Deine Vorbereitungsroutine 🎯 <a class="header-anchor" href="#folie-13-werkzeug-nr-2-–-deine-vorbereitungsroutine-🎯" aria-label="Permalink to &quot;Folie 13: Werkzeug Nr. 2 – Deine Vorbereitungsroutine 🎯&quot;">​</a></h2><h3 id="automatische-konsistenz-erstellen" tabindex="-1">Automatische Konsistenz erstellen <a class="header-anchor" href="#automatische-konsistenz-erstellen" aria-label="Permalink to &quot;Automatische Konsistenz erstellen&quot;">​</a></h3><p><strong>Die 4-Schritte-Routine:</strong></p><p><strong>1️⃣ VISUALISIEREN (3 Sekunden)</strong> Stell dir den perfekten Schuss vor. Sieh zu, wie er genau dort landet, wo du ihn haben willst.</p><p><strong>2️⃣ ATMEN (2 Sekunden)</strong> Einmal tief durchatmen. Vom Planungs- in den Ausführungsmodus wechseln.</p><p><strong>3️⃣ ANKER (2 Sekunden)</strong> Berühre deine Boulekugel. Spüre das Gewicht. Körperliche Verbindung.</p><p><strong>4️⃣ AUSFÜHREN (2 Sekunden)</strong> Vertraue vollkommen. Lass deinen Körper das tun, was er kann.</p><p><strong>⏱️ Gesamt: 9 Sekunden. Jedes Mal gleich.</strong></p><h3 id="warum-es-funktioniert" tabindex="-1">Warum es funktioniert: <a class="header-anchor" href="#warum-es-funktioniert" aria-label="Permalink to &quot;Warum es funktioniert:&quot;">​</a></h3><p><strong>Konstanz = Vertrauen = Leistung</strong></p><hr><h2 id="folie-14-werkzeug-nr-3-–-fehlerkorrekturprotokoll-🔄" tabindex="-1">Folie 14: Werkzeug Nr. 3 – Fehlerkorrekturprotokoll 🔄 <a class="header-anchor" href="#folie-14-werkzeug-nr-3-–-fehlerkorrekturprotokoll-🔄" aria-label="Permalink to &quot;Folie 14: Werkzeug Nr. 3 – Fehlerkorrekturprotokoll 🔄&quot;">​</a></h2><h3 id="fehlschuss-hier-ist-ihre-4-schritte-wiederherstellung" tabindex="-1">Fehlschuss? Hier ist Ihre 4-Schritte-Wiederherstellung: <a class="header-anchor" href="#fehlschuss-hier-ist-ihre-4-schritte-wiederherstellung" aria-label="Permalink to &quot;Fehlschuss? Hier ist Ihre 4-Schritte-Wiederherstellung:&quot;">​</a></h3><p><strong>1️⃣ BESTÄTIGEN (2 Sekunden)</strong> „Das lief nicht wie geplant.“ (Keine Wertung, nur eine Tatsache)</p><p><strong>2️⃣ LOSLASSEN (3 Sekunden)</strong> Körperliche Erholung: Hände schütteln, Schultern kreisen, 3 Schritte gehen.</p><p><strong>3️⃣ FOKUS (3 Sekunden)</strong> „Der nächste Schuss ist eine NEUE Chance.“ (Kein Bezug zum letzten Schuss)</p><p><strong>4️⃣ AUSFÜHREN (Nutze deine Routine)</strong> Vertraue deiner Vorbereitungsroutine. Ein Neuanfang.</p><h3 id="die-wichtigste-erkenntnis" tabindex="-1">Die wichtigste Erkenntnis: <a class="header-anchor" href="#die-wichtigste-erkenntnis" aria-label="Permalink to &quot;Die wichtigste Erkenntnis:&quot;">​</a></h3><p><strong>Jede Aufnahme ist unabhängig. Fehler sollten nicht wiederholt werden.</strong></p><p><em>Die besten Spieler vergessen schlechte Schläge am schnellsten.</em></p><hr><h2 id="folie-15-mal-ehrlich-–-was-halt-dich-auf-💬" tabindex="-1">Folie 15: Mal ehrlich – Was hält dich auf? 💬 <a class="header-anchor" href="#folie-15-mal-ehrlich-–-was-halt-dich-auf-💬" aria-label="Permalink to &quot;Folie 15: Mal ehrlich – Was hält dich auf? 💬&quot;">​</a></h2><h3 id="gruppendiskussion-5-minuten" tabindex="-1">Gruppendiskussion (5 Minuten) <a class="header-anchor" href="#gruppendiskussion-5-minuten" aria-label="Permalink to &quot;Gruppendiskussion (5 Minuten)&quot;">​</a></h3><p><strong>Wir freuen uns auf Ihre Rückmeldung:</strong></p><p><strong>Frage 1:</strong><em>„Wann fühlen Sie sich am meisten im Flow? Welche Bedingungen helfen dabei?“</em></p><p><strong>Frage 2:</strong><em>„Was ist deine größte mentale Herausforderung im Wettkampf?“</em></p><p><strong>Frage 3:</strong><em>„Welches dieser Tools spricht Sie am meisten an?“</em></p><ul><li>3-Atemzug-Reset</li><li>Routine vor der Impfung</li><li>Inner Coach-Reframing</li><li>Fehlerkorrektur</li></ul><p><strong>Teilt eure Gedanken offen – dies ist ein geschützter Raum!</strong></p><hr><h2 id="folie-16-ihr-aktionsplan-–-wahlen-sie-einen-✅" tabindex="-1">Folie 16: Ihr Aktionsplan – Wählen Sie EINEN! ✅ <a class="header-anchor" href="#folie-16-ihr-aktionsplan-–-wahlen-sie-einen-✅" aria-label="Permalink to &quot;Folie 16: Ihr Aktionsplan – Wählen Sie EINEN! ✅&quot;">​</a></h2><h3 id="die-herausforderung-dieser-woche" tabindex="-1">Die Herausforderung dieser Woche: <a class="header-anchor" href="#die-herausforderung-dieser-woche" aria-label="Permalink to &quot;Die Herausforderung dieser Woche:&quot;">​</a></h3><p><strong>Wähle NUR EINE Technik zum Üben aus:</strong></p><p><strong>Option A: 🌬️ 3-Atemzüge-Reset</strong> Nach jedem Fehler im Training anwenden</p><p><strong>Option B: 🎯 Vorbereitungsroutine</strong> Bei jedem Wurf wird die gleiche 4-Schritte-Routine ausgeführt.</p><p><strong>Option C: 💬 Innerer Coach</strong> Formulieren Sie pro Sitzung EINEN kritischen Gedanken neu.</p><p><strong>Option D: 🔄 Modusumschaltung</strong> Übungsplanung → Ausführungswechsel</p><h3 id="warum-nur-einer" tabindex="-1">Warum nur einer? <a class="header-anchor" href="#warum-nur-einer" aria-label="Permalink to &quot;Warum nur einer?&quot;">​</a></h3><p><strong>Beherrschen Sie ein Werkzeug, bevor Sie ein weiteres erlernen.</strong><em>In der mentalen Ausbildung ist Tiefe wichtiger als Breite.</em></p><hr><h2 id="folie-17-verfolge-deinen-fortschritt-📊" tabindex="-1">Folie 17: Verfolge deinen Fortschritt 📊 <a class="header-anchor" href="#folie-17-verfolge-deinen-fortschritt-📊" aria-label="Permalink to &quot;Folie 17: Verfolge deinen Fortschritt 📊&quot;">​</a></h2><h3 id="was-diese-woche-zu-beachten-ist" tabindex="-1">Was diese Woche zu beachten ist: <a class="header-anchor" href="#was-diese-woche-zu-beachten-ist" aria-label="Permalink to &quot;Was diese Woche zu beachten ist:&quot;">​</a></h3><p><strong>🎯 Flow-Momente:</strong></p><ul><li>Wann haben Sie sich „im Flow“ gefühlt?</li><li>Zu welcher Tageszeit?</li><li>Um welche Art von Aufnahme handelt es sich?</li><li>Was hat Ihnen dabei geholfen, dorthin zu gelangen?</li></ul><p><strong>💪 Erfolgreiche Technik:</strong></p><ul><li>Welches Werkzeug hat am besten funktioniert?</li><li>Wann hast du es benutzt?</li><li>Was war das Ergebnis?</li></ul><p><strong>📝 Führe ein einfaches Protokoll:</strong><em>„Nach einem Fehler die 3-Atemzug-Technik angewendet → fühlte mich ruhiger → traf den nächsten Schuss“</em></p><h3 id="das-ziel" tabindex="-1">Das Ziel: <a class="header-anchor" href="#das-ziel" aria-label="Permalink to &quot;Das Ziel:&quot;">​</a></h3><p><strong>Finde DEINE Muster. Baue DEIN System auf.</strong></p><hr><h2 id="folie-18-setze-deine-reise-fort-🚀" tabindex="-1">Folie 18: Setze deine Reise fort 🚀 <a class="header-anchor" href="#folie-18-setze-deine-reise-fort-🚀" aria-label="Permalink to &quot;Folie 18: Setze deine Reise fort 🚀&quot;">​</a></h2><h3 id="kostenlose-ressourcen-auf-carreau-app" tabindex="-1">Kostenlose Ressourcen auf carreau.app: <a class="header-anchor" href="#kostenlose-ressourcen-auf-carreau-app" aria-label="Permalink to &quot;Kostenlose Ressourcen auf carreau.app:&quot;">​</a></h3><p><strong>📚 Tiefgehende Analysen:</strong></p><ul><li><strong>Die Zone</strong> – Master-Flow-Zustände</li><li><strong>Mentale Stärke</strong> – Fortschrittliches Stressmanagement</li><li><strong>Teamdynamik</strong> – Kommunikation und Vertrauen</li><li><strong>Achtsamkeit</strong> – Fokus auf den gegenwärtigen Moment</li></ul><p><strong>🛠️ Praktische Hilfsmittel:</strong></p><ul><li><strong>Zielvorlage</strong> – Strukturieren Sie Ihre Entwicklung</li><li><strong>Tagebuchvorlage</strong> – Täglichen Fortschritt verfolgen</li><li><strong>Workshop-Leitfaden</strong> – Leiten Sie Ihre eigenen Kurse</li></ul><p><strong>Alles kostenlos. Alles zugänglich. Alles für Spitzenspieler entwickelt.</strong></p><hr><h2 id="folie-19-die-4-großen-ideen-💡" tabindex="-1">Folie 19: Die 4 großen Ideen 💡 <a class="header-anchor" href="#folie-19-die-4-großen-ideen-💡" aria-label="Permalink to &quot;Folie 19: Die 4 großen Ideen 💡&quot;">​</a></h2><h3 id="nehmen-sie-diese-mit-nach-hause" tabindex="-1">Nehmen Sie diese mit nach Hause: <a class="header-anchor" href="#nehmen-sie-diese-mit-nach-hause" aria-label="Permalink to &quot;Nehmen Sie diese mit nach Hause:&quot;">​</a></h3><p><strong>1️⃣ Flow ist eine FÄHIGKEIT, kein Glück</strong> Sie können lernen, bei Bedarf darauf zuzugreifen.</p><p><strong>2️⃣ Deine innere Stimme prägt deine Leistung</strong> Coache dich selbst, kritisiere dich nicht selbst.</p><p><strong>3️⃣ Einfache Werkzeuge funktionieren auch unter Druck</strong> Drei Atemzüge. Eine Routine. Ein Neustart. Das ist alles.</p><p><strong>4️⃣ Übung macht den Meister</strong> Mentale Fähigkeiten müssen genauso trainiert werden wie technische Fähigkeiten.</p><h3 id="die-wahrheit-1" tabindex="-1">Die Wahrheit: <a class="header-anchor" href="#die-wahrheit-1" aria-label="Permalink to &quot;Die Wahrheit:&quot;">​</a></h3><p>Mentales Training ist nicht mystisch. Es ist praktisch.</p><hr><h2 id="folie-20-fragen-sprechen-wir-daruber-💬" tabindex="-1">Folie 20: Fragen? Sprechen wir darüber! 💬 <a class="header-anchor" href="#folie-20-fragen-sprechen-wir-daruber-💬" aria-label="Permalink to &quot;Folie 20: Fragen? Sprechen wir darüber! 💬&quot;">​</a></h2><h1 id="offene-diskussion" tabindex="-1">Offene Diskussion <a class="header-anchor" href="#offene-diskussion" aria-label="Permalink to &quot;Offene Diskussion&quot;">​</a></h1><p>Welche Fragen haben Sie?</p><p><strong>Welche Erfahrungen möchten Sie teilen?</strong></p><p><strong>Welchen Herausforderungen stehen Sie gegenüber?</strong></p><p><strong>Was wirst du zuerst ausprobieren?</strong></p><p><em>Dies ist IHRE Sitzung. Lassen Sie uns sie für SIE wertvoll gestalten.</em></p><hr><h2 id="folie-21-deine-herausforderung-🎯" tabindex="-1">Folie 21: Deine Herausforderung 🎯 <a class="header-anchor" href="#folie-21-deine-herausforderung-🎯" aria-label="Permalink to &quot;Folie 21: Deine Herausforderung 🎯&quot;">​</a></h2><h1 id="die-mission-dieser-woche" tabindex="-1">Die Mission dieser Woche: <a class="header-anchor" href="#die-mission-dieser-woche" aria-label="Permalink to &quot;Die Mission dieser Woche:&quot;">​</a></h1><p><strong>1️⃣ Wähle EIN Werkzeug aus</strong> (3-Atemzug-Reset, Vorbereitungsroutine, Innerer Coach oder Moduswechsel)</p><p><strong>2️⃣ Übe es in jeder Trainingseinheit</strong> (Konstanz schlägt Intensität)</p><p><strong>3️⃣ Achten Sie auf die Veränderungen</strong> (Verfolge deinen Fortschritt)</p><p><strong>4️⃣ Teile deine Ergebnisse</strong> (Mit deinen Trainingspartnern oder auf carreau.app)</p><h3 id="erinnern" tabindex="-1">Erinnern: <a class="header-anchor" href="#erinnern" aria-label="Permalink to &quot;Erinnern:&quot;">​</a></h3><p><strong>Kleine Veränderungen → Große Ergebnisse</strong></p><hr><h2 id="folie-22-vielen-dank-🙏" tabindex="-1">Folie 22: Vielen Dank! 🙏 <a class="header-anchor" href="#folie-22-vielen-dank-🙏" aria-label="Permalink to &quot;Folie 22: Vielen Dank! 🙏&quot;">​</a></h2><h1 id="du-schaffst-das" tabindex="-1">Du schaffst das! <a class="header-anchor" href="#du-schaffst-das" aria-label="Permalink to &quot;Du schaffst das!&quot;">​</a></h1><p><strong>Was Sie heute gelernt haben:</strong></p><ul><li>✅ Wie man auf Flow-Zustände zugreift</li><li>✅ Wie Sie Ihren inneren Kritiker in den Griff bekommen</li><li>✅ Praktische Werkzeuge, die auch unter Druck funktionieren</li><li>✅ Ein klarer Aktionsplan für diese Woche</li></ul><p><strong>Nächste Schritte:</strong></p><ol><li>Wähle deine EINE Technik</li><li>Übe es konsequent</li><li>Besuchen Sie carreau.app für weitere Ressourcen</li><li>Teile deinen Fortschritt mit der Gruppe.</li></ol><h3 id="die-reise-beginnt-jetzt" tabindex="-1">Die Reise beginnt jetzt: <a class="header-anchor" href="#die-reise-beginnt-jetzt" aria-label="Permalink to &quot;Die Reise beginnt jetzt:&quot;">​</a></h3><p><strong>Mentales Training ist praktisch, nicht mystisch.</strong><strong>Starten Sie noch heute. Erste Ergebnisse schon bald.</strong></p><hr><p><em>Pétanque Academy – Elite-Spielerentwicklung</em><em>carreau.app – Kostenlose Ressourcen für Elite-Spieler</em></p>',201)])])}]]);export{t as __pageData,a as default};
